#!/usr/bin/env bash
# PartsDonor F8 executor via Pi headless (auth screens: login/registration, adaptive, JWT)
set -e
cd /home/aifactory/PartsDonor
OUT=/home/aifactory/PartsDonor/frontend/_f8_pi_run.log
PI_PROMPT='Read /home/aifactory/PartsDonor/_f8_spec.md CAREFULLY. Execute the PartsDonor F8 frontend auth module exactly as specified. Backend B8 auth is LIVE on http://127.0.0.1:8001 (vite /api proxy rewrites /api -> backend root, so frontend calls the proxy at /api/auth/register and /api/auth/login). VERIFIED as of now: POST /api/auth/register {email,password,role:"buyer"|"seller",company_name?} -> 201 UserOut (no token returned); POST /api/auth/login {email,password} -> {access_token,token_type,role,user_id}; bad login -> 401 {"detail":"Неверный email или пароль"}; email must use a real non-reserved domain (e.g. @gmail.com), @test.local/@example.com get 422. Deliverables: (1) new file frontend/src/pages/Auth.jsx exporting AuthPage handling /login and /register modes; (2) a tiny session helper (recommend frontend/src/auth.jsx) that reads/writes localStorage keys "pd-token" (raw JWT, already consumed by DonorView.jsx and Deal.jsx for protected PATCH/actions) and "pd-session" (JSON {token,role,user_id,email}); (3) wire routes /login and /register plus a session-aware header auth block (show role+email+Выйти when logged in, else a Войти NavLink) into frontend/src/App.jsx — PRESERVE all existing routes/nav, only ADD; (4) add a clearly-marked F8 CSS section (pd-f8-* classes) to frontend/src/styles.css: centered auth card, role/segment tabs, reuse existing .pd-input/.pd-btn-primary, error/ok banners, touch-friendly rows, responsive at <=480px, no horizontal overflow at 390px and 1440px. Auth flow: register (role toggle shows company_name field only for seller) -> POST /api/auth/register -> on 201 redirect to /login with a success banner "Регистрация прошла — войдите"; login -> POST /api/auth/login -> on 200 store pd-token and pd-session then role-aware redirect (seller->/cabinet, buyer->/buyer, else /); show inline error on 401. Do NOT gate existing routes behind auth. Do NOT touch backend/* or other pages beyond App.jsx/styles.css. Run npm run build and fix until it exits 0. Then verify LIVE: backend 127.0.0.1:8001 and vite 127.0.0.1:5173 are already running — via the served app (or curl through /api) register a buyer and a seller, login each, confirm localStorage pd-token+pd-session set and correct redirect, bad login shows inline error; confirm no horizontal overflow at 390px and 1440px. Take screenshots pd-f8-login-desktop.png, pd-f8-login-mobile.png, and (if feasible) pd-f8-register-desktop.png into /home/aifactory/PartsDonor/. Report the list of changed files, build result, verification checks, and screenshot absolute paths. Keep output concise.'
pi -p "$PI_PROMPT" --provider wormsoft --model deepseek-ai/deepseek-v4-pro > "$OUT" 2>&1
echo "PI_EXIT=$?" >> "$OUT"